formulas.rawText:
{
  "originalFormula": "g_m = k_p(V_G - V_T)(1 + \lambda_p V_D)",
  "genericFormula": "g_m = k_p(V_G - V_T)(1 + \lambda_p V_D)",
  "description": "Esta fórmula representa a transcondutância de um transistor de efeito de campo (FET), que é uma medida de quão bem o dispositivo pode controlar a corrente elétrica que flui através dele, em resposta a uma tensão de entrada. A transcondutância é uma característica importante que indica a eficiência do transistor em amplificar sinais.",
  "concepts": [
    "Transcondutância",
    "Transistor de Efeito de Campo (FET)",
    "Tensão de gate",
    "Tensão de limiar",
    "Tensão de dreno",
    "Parâmetro de canal"
  ],
  "symbols": [
    {
      "symbol": "g_m",
      "description": "Representa a transcondutância, que é a relação entre a variação da corrente de dreno e a variação da tensão de gate, indicando a capacidade de amplificação do transistor."
    },
    {
      "symbol": "k_p",
      "description": "É a constante de transcondutância do transistor, que depende das propriedades do material semicondutor e da geometria do dispositivo."
    },
    {
      "symbol": "V_G",
      "description": "Representa a tensão aplicada ao terminal de gate do transistor, que controla a corrente que flui entre o dreno e a fonte."
    },
    {
      "symbol": "V_T",
      "description": "É a tensão de limiar, que é a tensão mínima necessária no gate para que o transistor comece a conduzir corrente."
    },
    {
      "symbol": "λ_p",
      "description": "É o parâmetro de canal que representa a modulação da transcondutância em função da tensão de dreno, indicando como a corrente de dreno é afetada pela tensão aplicada."
    },
    {
      "symbol": "V_D",
      "description": "Representa a tensão aplicada ao terminal de dreno do transistor, que influencia a corrente que flui entre o dreno e a fonte."
    }
  ]
}
